//! Reads `reman.toml` declarations and files generated by `reman init`, including settings inheritance
//! through repository → workspace → project.

mod settings;

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, anyhow};
use indexmap::IndexMap;
use serde::{Deserialize, Serialize};
pub use settings::{ProjectBase, ProjectSettings, Setting};
use strum::{Display, EnumString, VariantNames};

use crate::language::{FileTree, Language};

/// File name reman looks for.
pub const FILE_NAME: &str = "reman.toml";

/// A single `reman.toml` document.
#[derive(Debug, Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct File {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub repository: Option<RepositoryTable>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub workspace: Option<WorkspaceTable>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub project: Option<ProjectTable>,
    /// Per-language workspace defaults, valid only at the root.
    #[serde(default, skip_serializing_if = "IndexMap::is_empty")]
    pub languages: IndexMap<&'static dyn Language, LanguageTable>,
    /// Uses tasks from the most specific role: project, then workspace, then repository.
    #[serde(default, skip_serializing_if = "IndexMap::is_empty")]
    pub tasks: IndexMap<String, TaskTable>,
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct RepositoryTable {
    /// GitHub repository in `owner/name` form.
    pub github: String,
    /// App release tag template using `{name}` and `{version}`.
    #[serde(default = "RepositoryTable::default_tag")]
    pub tag: String,
    /// Root-relative directory containing change files.
    #[serde(default = "RepositoryTable::default_changes")]
    pub changes: String,
    /// Default settings shared by all projects.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub project: Option<ProjectDefaultTable>,
}

impl RepositoryTable {
    pub fn new(github: String) -> Self {
        RepositoryTable {
            github,
            tag: Self::default_tag(),
            changes: Self::default_changes(),
            project: None,
        }
    }

    fn default_tag() -> String {
        "{name}/v{version}".to_owned()
    }

    fn default_changes() -> String {
        ".changes".to_owned()
    }
}

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct WorkspaceTable {
    pub language: &'static dyn Language,
    /// Workspace of packages for development only (fixtures, test peers): none of them is a project.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub development: bool,
    /// Default settings inherited by workspace projects.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub project: Option<ProjectDefaultTable>,
}

#[derive(Debug, Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct LanguageTable {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub select: Option<Select>,
    #[serde(default, skip_serializing_if = "IndexMap::is_empty")]
    pub tasks: IndexMap<String, TaskTable>,
}

#[derive(Clone, Debug, Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ProjectDefaultTable {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub changelog: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub skip: Option<Vec<String>>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ProjectTable {
    pub kind: Kind,
    /// Enables GitHub tagging and releases for an app (default: true for apps).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub release: Option<bool>,
    /// Marks the app's GitHub release as repository-latest; only one project may do so.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub latest: bool,
    /// Overrides the repository release tag with `{name}` and `{version}`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tag: Option<String>,
    /// Declares shipped or built project dependencies absent from manifests by ID or unique name.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub uses: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub changelog: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub skip: Option<Vec<String>>,
}

impl ProjectTable {
    /// Project of `kind` with every other setting inherited.
    pub fn new(kind: Kind) -> Self {
        ProjectTable {
            kind,
            release: None,
            latest: false,
            tag: None,
            uses: Vec::new(),
            changelog: None,
            skip: None,
        }
    }
}

/// Project kind.
#[derive(
    Clone, Copy, Debug, Deserialize, Display, EnumString, Eq, PartialEq, Serialize, VariantNames,
)]
#[serde(rename_all = "lowercase")]
#[strum(serialize_all = "lowercase")]
pub enum Kind {
    /// Program people run: tagged and released on GitHub unless `release = false`.
    App,
    /// Page deployed from main: versioned, never tagged.
    Site,
    /// Library code or definitions consumed by other projects.
    Library,
}

impl Kind {
    pub fn parse(text: &str) -> Result<Self> {
        text.parse()
            .map_err(|_| anyhow!("`{text}` is not a kind: {}", Kind::VARIANTS.join(", ")))
    }
}

/// Workspace package selection: `all` selects every package; `each` runs per package with `{name}`.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Select {
    pub all: String,
    pub each: String,
}

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum PackageFilter {
    /// All packages.
    All,
    /// Selects packages with library targets, including doc tests.
    Library,
}

/// Task as one file declares it; fields it omits retain what the files above set.
#[derive(Clone, Debug, Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct TaskTable {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub suite: Option<String>,
    /// Command checking (or testing).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub run: Option<String>,
    /// Command fixing what `run` reports (lints only).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub fix: Option<String>,
    /// Command working directory relative to the declaring file.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub cwd: Option<String>,
    #[serde(default, skip_serializing_if = "IndexMap::is_empty")]
    pub env: IndexMap<String, String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub select: Option<Select>,
    /// Packages allowed for `{packages}`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub packages: Option<PackageFilter>,
    /// Requires all instances of these task keys to run first.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub after: Option<Vec<String>>,
    /// Language a repository task belongs to, for `--language`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub language: Option<&'static dyn Language>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub enabled: Option<bool>,
}

impl TaskTable {
    /// Overlays `other` onto `self`, replacing set fields and merging `env` by key.
    pub fn merge(&self, other: &TaskTable) -> TaskTable {
        let mut env = self.env.clone();

        env.extend(other.env.clone());

        TaskTable {
            suite: other.suite.clone().or_else(|| self.suite.clone()),
            run: other.run.clone().or_else(|| self.run.clone()),
            fix: other.fix.clone().or_else(|| self.fix.clone()),
            cwd: other.cwd.clone().or_else(|| self.cwd.clone()),
            env,
            select: other.select.clone().or_else(|| self.select.clone()),
            packages: other.packages.or(self.packages),
            after: other.after.clone().or_else(|| self.after.clone()),
            language: other.language.or(self.language),
            enabled: other.enabled.or(self.enabled),
        }
    }
}

impl File {
    pub fn read(path: &Path) -> Result<Self> {
        let text =
            std::fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;

        Self::parse(&text, path)
    }

    /// `reman.toml` files below `root`, keyed by root-relative folder, with `overlay`'s (files not
    /// written yet) over those on disk.
    pub fn read_all(
        root: &Path,
        overlay: &[(PathBuf, String)],
    ) -> Result<BTreeMap<PathBuf, (PathBuf, File)>> {
        let is_file = |path: &Path| path.file_name().is_some_and(|name| name == FILE_NAME);
        let folder = |path: &Path| path.parent().unwrap_or(Path::new("")).to_path_buf();
        let mut files = BTreeMap::new();

        for path in FileTree::new(root).files(Path::new(""), is_file) {
            let file = File::read(&root.join(&path))?;

            files.insert(folder(&path), (path, file));
        }

        for (path, text) in overlay.iter().filter(|(path, _)| is_file(path)) {
            files.insert(folder(path), (path.clone(), File::parse(text, path)?));
        }

        Ok(files)
    }

    /// File `path` would be with `text`.
    pub fn parse(text: &str, path: &Path) -> Result<Self> {
        toml::from_str(text)
            .with_context(|| format!("{} is not a valid reman.toml", path.display()))
    }

    pub fn render(&self) -> Result<String> {
        Ok(toml::to_string(self)?)
    }
}
